\":{\"description\":\"ReplicationControllerStatus represents the current status of a replication controller.\",\"properties\":{\"availableReplicas\":{\"description\":\"The number of available replicas (ready for at least minReadySeconds) for this replication controller.\",\"format\":\"int32\",\"type\":\"integer\"},\"conditions\":{\"description\":\"Represents the latest available observations of a replication controller's current state.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-a1b7b568883e44149862.json#/components/schemas/io.k8s.api.core.v1.ReplicationControllerCondition\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-map-keys\":[\"type\"],\"x-kubernetes-list-type\":\"map\",\"x-kubernetes-patch-merge-key\":\"type\",\"x-kubernetes-patch-strategy\":\"merge\",\"nullable\":true},\"fullyLabeledReplicas\":{\"description\":\"The number of pods that have labels matching the labels of the pod template of the replication controller.\",\"format\":\"int32\",\"type\":\"integer\"},\"observedGeneration\":{\"description\":\"ObservedGeneration reflects the generation of the most recently observed replication controller.\",\"format\":\"int64\",\"type\":\"integer\"},\"readyReplicas\":{\"description\":\"The number of ready replicas for this replication controller.\",\"format\":\"int32\",\"type\":\"integer\"},\"replicas\":{\"default\":0,\"description\":\"Replicas is the most recently observed number of replicas. More info: https://kubernetes.io/docs/concepts/workloads/controllers/replicationcontroller#what-is-a-replicationcontroller\",\"format\":\"int32\",\"type\":\"integer\"}},\"required\":[\"replicas\"],\"type\":\"object\"},\"io.k8s.api.core.v1.ResourceClaim\":{\"description\":\"ResourceClaim references one entry in PodSpec.ResourceClaims.\",\"properties\":{\"name\":{\"default\":\"\",\"description\":\"Name must match the name of one entry in pod.spec.resourceClaims of the Pod where this field is used. It makes that resource available inside a container.\",\"typ