    labelselector::Union{Absent,IoK8sApimachineryPkgApisMetaV1LabelSelector,Nothing} = ABSENT
    matchlabelkeys::Union{Absent,Union{Nothing,Vector{String}}} = ABSENT
    mismatchlabelkeys::Union{Absent,Union{Nothing,Vector{String}}} = ABSENT
    namespaceselector::Union{Absent,IoK8sApimachineryPkgApisMetaV1LabelSelector,Nothing} = ABSENT
    namespaces::Union{Absent,Union{Nothing,Vector{String}}} = ABSENT
    topologykey::String
    additional_properties::Dict{String,Any} = Dict{String,Any}()
end
