    allocatedresourcestatuses::Union{Absent,IoK8sApiCoreV1PersistentVolumeClaimStatusAllocatedResourceStatuses,Nothing} = ABSENT
    allocatedresources::Union{Absent,IoK8sApiCoreV1PersistentVolumeClaimStatusAllocatedResources,Nothing} = ABSENT
    capacity::Union{Absent,IoK8sApiCoreV1PersistentVolumeClaimStatusCapacity,Nothing} = ABSENT
    conditions::Union{Absent,Union{Nothing,Vector{IoK8sApiCoreV1PersistentVolumeClaimCondition}}} = ABSENT
    currentvolumeattributesclassname::Union{Absent,Nothing,String} = ABSENT
    modifyvolumestatus::Union{Absent,IoK8sApiCoreV1ModifyVolumeStatus,Nothing} = ABSENT
    phase::Union{Absent,Nothing,String} = ABSENT
    additional_properties::Dict{String,Any} = Dict{String,Any}()
end
