    _openapi_values[:name] = name
    _openapi_values[:namespace] = namespace
    _openapi_values[:pretty] = pretty
    _openapi_values[:dryrun] = dryrun
    _openapi_values[:fieldmanager] = fieldmanager
    _openapi_values[:fieldvalidation] = fieldvalidation
    _openapi_values[:force] = force
    return _request(client, _OP_patchcorev1namespacedresourcequota, _openapi_values; body = body, content_type, accept, with_http_info, request_headers, request_options, stream_to)
end

