    _openapi_values = Dict{Symbol,Any}()
    _openapi_values[:allowwatchbookmarks] = allowwatchbookmarks
    _openapi_values[:continue_] = continue_
    _openapi_values[:fieldselector] = fieldselector
    _openapi_values[:labelselector] = labelselector
    _openapi_values[:limit] = limit
    _openapi_values[:namespace] = namespace
    _openapi_values[:pretty] = pretty
    _openapi_values[:resourceversion] = resourceversion
    _openapi_values[:resourceversionmatch] = resourceversionmatch
    _openapi_values[:sendinitialevents] = sendinitialevents
    _openapi_values[:timeoutseconds] = timeoutseconds
    _openapi_values[:watch] = watch
    return _request(client, _OP_watchcorev1namespacedsecretlist, _openapi_values; body = ABSENT, content_type, accept, with_http_info, request_headers, request_options, stream_to)
end

